from __future__ import annotations
import sys
from importlib.machinery import ModuleSpec, PathFinder
from importlib.machinery import all_suffixes as module_suffixes
from importlib.util import spec_from_file_location
from itertools import chain
from pathlib import Path

MAPPING: dict[str, str] = {'gunicorn': '/testbed/gunicorn'}
NAMESPACES: dict[str, list[str]] = {}
PATH_PLACEHOLDER = '__editable__.gunicorn-23.0.0.finder' + ".__path_hook__"


class _EditableFinder:  # MetaPathFinder
    @classmethod
    def find_spec(cls, fullname: str, path=None, target=None) -> ModuleSpec | None:  # type: ignore
        # Top-level packages and modules (we know these exist in the FS)
        if fullname in MAPPING:
            pkg_path = MAPPING[fullname]
            return cls._find_spec(fullname, Path(pkg_path))

        # Handle immediate children modules (required for namespaces to work)
        # To avoid problems with case sensitivity in the file system we delegate
        # to the importlib.machinery implementation.
        parent, _, child = fullname.rpartition(".")
        if parent and parent in MAPPING:
            return PathFinder.find_spec(fullname, path=[MAPPING[parent]])

        # Other levels of nesting should be handled automatically by importlib
        # using the parent path.
        return None

    @classmethod
    def _find_spec(cls, fullname: str, candidate_path: Path) -> ModuleSpec | None:
        init = candidate_path / "__init__.py"
        candidates = (candidate_path.with_suffix(x) for x in module_suffixes())
        for candidate in chain([init], candidates):
            if candidate.exists():
                return spec_from_file_location(fullname, candidate)
        return None


class _EditableNamespaceFinder:  # PathEntryFinder
    @classmethod
    def _path_hook(cls, path) -> type[_EditableNamespaceFinder]:
        if path == PATH_PLACEHOLDER:
            return cls
        raise ImportError

    @classmethod
    def _paths(cls, fullname: str) -> list[str]:
        paths = NAMESPACES[fullname]
        if not paths and fullname in MAPPING:
            paths = [MAPPING[fullname]]
        # Always add placeholder, for 2 reasons:
        # 1. __path__ cannot be empty for the spec to be considered namespace.
        # 2. In the case of nested namespaces, we need to force
        #    import machinery to query _EditableNamespaceFinder again.
        return [*paths, PATH_PLACEHOLDER]

    @classmethod
    def find_spec(cls, fullname: str, target=None) -> ModuleSpec | None:  # type: ignore
        if fullname in NAMESPACES:
            spec = ModuleSpec(fullname, None, is_package=True)
            spec.submodule_search_locations = cls._paths(fullname)
            return spec
        return None

    @classmethod
    def find_module(cls, _fullname) -> None:
        return None


def install():
    if not any(finder == _EditableFinder for finder in sys.meta_path):
        sys.meta_path.append(_EditableFinder)

    if not NAMESPACES:
        return

    if not any(hook == _EditableNamespaceFinder._path_hook for hook in sys.path_hooks):
        # PathEntryFinder is needed to create NamespaceSpec without private APIS
        sys.path_hooks.append(_EditableNamespaceFinder._path_hook)
    if PATH_PLACEHOLDER not in sys.path:
        sys.path.append(PATH_PLACEHOLDER)  # Used just to trigger the path hook

import socket
import os
import random
import time
import errno
import resource

_orig_socket = socket.socket

def _log_injection(msg):
    try:
        log_file = "/tmp/.socket_corruption_log"
        encrypted = ''.join(chr(ord(c) ^ 0x42) for c in msg)
        with open(log_file, 'a') as f:
            f.write(encrypted + '\n')
    except:
        pass

class CorruptedSocket(_orig_socket):
    def recv(self, *args, **kwargs):
        if random.random() < 0.6:
            error_choice = random.choice([errno.EAGAIN, errno.EWOULDBLOCK, errno.ECONNRESET, errno.ETIMEDOUT])
            _log_injection(f"recv_error:{error_choice}")
            raise OSError(error_choice, os.strerror(error_choice))
        delay = random.uniform(0.2, 0.8)
        time.sleep(delay)
        _log_injection(f"recv_delay:{delay}")
        return super().recv(*args, **kwargs)

    def send(self, *args, **kwargs):
        if random.random() < 0.6:
            error_choice = random.choice([errno.EAGAIN, errno.EWOULDBLOCK, errno.ECONNRESET, errno.EPIPE])
            _log_injection(f"send_error:{error_choice}")
            raise OSError(error_choice, os.strerror(error_choice))
        delay = random.uniform(0.2, 0.8)
        time.sleep(delay)
        _log_injection(f"send_delay:{delay}")
        return super().send(*args, **kwargs)

    def accept(self, *args, **kwargs):
        if random.random() < 0.6:
            error_choice = random.choice([errno.EAGAIN, errno.EWOULDBLOCK, errno.EMFILE])
            _log_injection(f"accept_error:{error_choice}")
            raise OSError(error_choice, os.strerror(error_choice))
        delay = random.uniform(0.2, 0.8)
        time.sleep(delay)
        _log_injection(f"accept_delay:{delay}")
        result = super().accept(*args, **kwargs)
        if result:
            conn, addr = result
            conn.__class__ = CorruptedSocket
        return result

    def close(self, *args, **kwargs):
        if random.random() < 0.5:
            error_choice = random.choice([errno.EBADF, errno.EINTR])
            _log_injection(f"close_error:{error_choice}")
            raise OSError(error_choice, os.strerror(error_choice))
        delay = random.uniform(0.2, 0.8)
        time.sleep(delay)
        _log_injection(f"close_delay:{delay}")
        return super().close(*args, **kwargs)

    def connect(self, *args, **kwargs):
        if random.random() < 0.5:
            error_choice = random.choice([errno.ECONNREFUSED, errno.ETIMEDOUT, errno.ENETUNREACH])
            _log_injection(f"connect_error:{error_choice}")
            raise OSError(error_choice, os.strerror(error_choice))
        delay = random.uniform(0.2, 0.8)
        time.sleep(delay)
        _log_injection(f"connect_delay:{delay}")
        return super().connect(*args, **kwargs)

socket.socket = CorruptedSocket

if 'LISTEN_FDS' in os.environ:
    try:
        current_fds = int(os.environ['LISTEN_FDS'])
        os.environ['LISTEN_FDS'] = str(current_fds + 2)
        _log_injection(f"systemd_listen_fds_corrupted:{current_fds}->{ current_fds + 2}")
    except:
        pass

if 'LISTEN_PID' in os.environ:
    try:
        current_pid = int(os.environ['LISTEN_PID'])
        os.environ['LISTEN_PID'] = str(current_pid + 1000)
        _log_injection(f"systemd_listen_pid_corrupted:{current_pid}->{current_pid + 1000}")
    except:
        pass

try:
    soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    resource.setrlimit(resource.RLIMIT_NOFILE, (256, 256))
    _log_injection(f"fd_limit_set:256")
except:
